### 三、可复现断言清单（供派发方浏览器复跑）

启动开发服务器后，在浏览器 Console 中执行以下断言序列进行验收：

#### 1. 打开/关闭与滚动锁引用计数
```js
import { openDetail, closeDetail, isDetailOpen } from './src/ui/parts/detailModal';
const store = window.__htl_store;
const eventId = store.getState().data.events[0].id;

openDetail(eventId, store);
console.assert(isDetailOpen() === true, 'isDetailOpen 必须为 true');
console.assert(document.querySelector('.htl-detail[data-detail][role="dialog"]') !== null, '浮层必须渲染在 DOM');
console.assert(document.body.classList.contains('is-locked') === true, 'body 必须添加 is-locked');

closeDetail();
console.assert(isDetailOpen() === false, 'isDetailOpen 必须为 false');
console.assert(document.querySelector('.htl-detail') === null, '浮层必须从 DOM 移除');
console.assert(document.body.classList.contains('is-locked') === false, 'body 必须移除 is-locked');
```

#### 2. ⏳T30 待补：点条目标题打开
> 标注：依赖 T30 在 `main.ts` 中接入 `openDetail` 分支。

#### 3. 3 条记录按日期递增且星级正确
```js
import { openDetail } from './src/ui/parts/detailModal';
const store = window.__htl_store;
// 选取一条含多条记录的事件（或用 store 构造）
const targetEvent = store.getState().data.events.find(e => e.records.length >= 3) || store.getState().data.events[0];
openDetail(targetEvent.id, store);

const records = document.querySelectorAll('.htl-detail__record');
const dates = [...records].map(r => r.querySelector('.htl-detail__record-date')?.textContent);
console.assert(dates.every((d, i) => i === 0 || d >= dates[i - 1]), '记录日期必须自上而下递增');

records.forEach(r => {
  const star = r.querySelector('.htl-star');
  console.assert(star !== null && /^[★☆]{5}$/.test(star.textContent), '星级符号格式必须严格为 5 颗星星组合');
});
```

#### 4. 配图开灯箱与滚动锁隔离
```js
const coverImg = document.querySelector('.htl-detail__cover img');
if (coverImg) {
  coverImg.click(); // 触发 openLightbox
  console.assert(document.querySelector('.htl-lightbox') !== null, '灯箱必须出现');
  console.assert(document.body.classList.contains('is-locked') === true, '滚动锁计数为 2，仍然保持锁定');

  // 关灯箱（按 ESC 或点灯箱背景）
  document.querySelector('.htl-lightbox').click();
  console.assert(document.querySelector('.htl-lightbox') === null, '灯箱关闭');
  console.assert(document.querySelector('.htl-detail') !== null, '详情浮层仍在');
  console.assert(document.body.classList.contains('is-locked') === true, '详情仍在，滚动锁计数 2->1，仍然锁定');
}
```

#### 5. 关联项数量与跨度文本
```js
import { openDetail } from './src/ui/parts/detailModal';
const store = window.__htl_store;
const eventWithRel = store.getState().data.events.find(e => e.relatedIds.length > 0);
if (eventWithRel) {
  openDetail(eventWithRel.id, store);
  const relButtons = document.querySelectorAll('.htl-detail__relations button');
  console.assert(relButtons.length >= eventWithRel.relatedIds.length, '关联按钮数与关联视图一致');
  relButtons.forEach(btn => {
    console.assert(/^[←→↔] \d{4}-\d{2}-\d{2} .* · .+$/.test(btn.textContent), '关联项文案必须包含方向箭头、日期、标题与跨度');
  });
}
```

#### 6. 操作按钮存在性
```js
console.assert(document.querySelector('.htl-detail__actions [data-action="add-record"]') !== null, '必须有添加记录按钮');
console.assert(document.querySelector('.htl-detail__actions [data-action="edit-event"]') !== null, '必须有编辑事件按钮');
console.assert(document.querySelector('.htl-detail__actions [data-action="delete-event"]') !== null, '必须有删除事件按钮');
```

#### 7. 遮罩点击与关闭按钮关闭（⏳T30 待补 ESC）
```js
import { openDetail, isDetailOpen } from './src/ui/parts/detailModal';
const store = window.__htl_store;
const eventId = store.getState().data.events[0].id;

// 1. 点关闭按钮
openDetail(eventId, store);
document.querySelector('.htl-detail [data-action="close-detail"]').click();
console.assert(isDetailOpen() === false && !document.body.classList.contains('is-locked'), '点击关闭按钮必须关闭且解锁');

// 2. 点遮罩背景
openDetail(eventId, store);
document.querySelector('.htl-detail').click(); // ev.target === modalEl
console.assert(isDetailOpen() === false && !document.body.classList.contains('is-locked'), '点击遮罩背景必须关闭且解锁');

// 3. 点 panel 内部空白不关闭
openDetail(eventId, store);
document.querySelector('.htl-detail__panel').click();
console.assert(isDetailOpen() === true, '点击面板内容区域不可关闭浮层');
```

#### 8. 数据就地更新：store.addRecord 记录数 +1
```js
import { openDetail, refreshDetail } from './src/ui/parts/detailModal';
const store = window.__htl_store;
const eventId = store.getState().data.events[0].id;
openDetail(eventId, store);

const beforeCount = document.querySelectorAll('.htl-detail__record').length;
store.addRecord({ eventId, date: '2026-11-19', rating: 5, summary: '自动化新增记录' });
refreshDetail(store.getState());

const afterCount = document.querySelectorAll('.htl-detail__record').length;
console.assert(afterCount === beforeCount + 1, '调用 refreshDetail 后记录数必须 +1');
console.assert(document.querySelector('.htl-detail') !== null, '浮层就地更新，不闪烁不关闭');
```

#### 9. 事件删除自动关闭并提示：store.deleteEvent
```js
import { openDetail, refreshDetail } from './src/ui/parts/detailModal';
const store = window.__htl_store;
// 创建一个临时事件并打开
const res = store.createEvent({ date: '2026-11-19', title: '临时测试删除事件' });
const tempId = res.value.event.id;
openDetail(tempId, store);

store.deleteEvent(tempId);
refreshDetail(store.getState());

console.assert(document.querySelector('.htl-detail') === null, '事件被删除后浮层必须自动关闭');
console.assert(document.body.classList.contains('is-locked') === false, '滚动锁必须释放');
console.assert(document.querySelector('.htl-toast-container')?.textContent?.includes('事件不存在或已被删除'), '必须弹出错误提示');
```

#### 10. 滚动行为隔离
```js
import { openDetail } from './src/ui/parts/detailModal';
const store = window.__htl_store;
const eventId = store.getState().data.events[0].id;
openDetail(eventId, store);

const panel = document.querySelector('.htl-detail__panel');
panel.scrollTop = 50;
console.assert(panel.scrollTop >= 0, 'panel 内部允许滚动');
console.assert(document.body.classList.contains('is-locked'), '页面背景处于锁定状态');
```
